<?php
namespace App\Http\Controllers;
use App\Models\{CertificateIssuanceLog,CertificateTemplate,ParishSetting,SacramentalRecord};use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class IssuanceController extends Controller { public function store(Request $r,SacramentalRecord $record){$name=trim(strip_tags((string)$r->input('requestor_name')));$purpose=trim(strip_tags((string)$r->input('purpose')));if(!$name||!$purpose)return response()->json(['error'=>'Requestor name and purpose are required'],422);$log=CertificateIssuanceLog::create(['sacramental_record_id'=>$record->id,'requestor_name'=>$name,'purpose'=>$purpose,'issued_by'=>$r->user()->id]);return response()->json(['data'=>['id'=>$log->id,'sacramental_record_id'=>$record->id,'requestor_name'=>$name,'purpose'=>$purpose]],201);} public function certificate(Request $r,SacramentalRecord $record){$log=CertificateIssuanceLog::whereKey($r->query('log_id'))->where('sacramental_record_id',$record->id)->first();if(!$log)return response()->json(['error'=>'Issuance log required'],404);$record->load('person');$p=ParishSetting::find(1);$t=CertificateTemplate::find($record->sacrament_type);$strong=fn($v)=>"<strong style='color:#101010;'>".e($v).'</strong>';$person=$record->person;$body=strtr(e($t->body_template),['{name}'=>$strong(trim($person->first_name.' '.$person->middle_name.' '.$person->last_name)),'{dob}'=>$strong($person->date_of_birth?->format('F j, Y')??'—'),'{fatherName}'=>$strong($person->father_name),'{motherName}'=>$strong($person->mother_maiden_name),'{eventDate}'=>$strong($record->event_date->format('F j, Y')),'{spouse}'=>$strong($person->spouse_name),'{sacrament}'=>$strong($record->sacrament_type),'{book}'=>e($record->book_number),'{page}'=>e($record->page_number),'{line}'=>e($record->line_number)]);$uri=fn($x)=>$x&&Storage::disk('public')->exists($x)?'data:'.Storage::disk('public')->mimeType($x).';base64,'.base64_encode(Storage::disk('public')->get($x)):null;return Pdf::loadView('certificates.certificate',['parish'=>$p,'record'=>$record,'title'=>$t->title_text,'body'=>$body,'footerNote'=>$t->footer_note,'priestName'=>$record->minister_name?:$p->default_priest_name,'today'=>now()->format('F j, Y'),'issuedTo'=>$log->requestor_name==='Not specified'?'____________________':$log->requestor_name,'purpose'=>$log->purpose,'sealDataUri'=>$uri($p->seal_image_path),'signatureDataUri'=>$uri($p->priest_signature_path)])->setPaper('letter','portrait')->stream('certificate-'.$record->id.'.pdf');} public function index(Request $r){$logs=CertificateIssuanceLog::with(['record.person','issuer'])->latest('issued_at')->get()->map(fn($l)=>['id'=>$l->id,'issuedTo'=>$l->requestor_name,'purpose'=>$l->purpose,'timestamp'=>$l->issued_at,'issuedBy'=>$l->issuer->full_name,'sacrament'=>$l->record->sacrament_type,'personName'=>trim($l->record->person->first_name.' '.$l->record->person->middle_name.' '.$l->record->person->last_name)]);return response()->json(['data'=>$logs,'meta'=>['total'=>$logs->count()]]);} }
